# inspect local occupancy counts for positive vs negatives
for rad in [1,2,3]:
 vals=[]
 for arr,pts,outs in [(D1,pts1,out1),(D2,pts2,out2)]:
  s=set(pts); o=set(outs)
  for r in range(16):
   for c in range(16):
    if arr[r,c] in (7,6):continue
    count=sum((r+dr,c+dc) in s for dr in range(-rad,rad+1) for dc in range(-rad,rad+1) if 0<=r+dr<16 and 0<=c+dc<16)
    vals.append((count,(r,c) in o))
 print(rad,Counter((n,p) for n,p in vals))
